begin;select plan(5);select has_table('public','settlement_events','events persist');insert into settlement_events(market_id,original_result,position_snapshot,payout_snapshot)values(4,'HOME','[]','[]');select ok((preview_settlement_recovery(4)->'event'->>'original_result')='HOME','details preserve result');select lives_ok($$select admin_recover_settlement(null,4,'AWAY','오정산 수정')$$,'recovery executes atomically');select throws_ok($$select admin_recover_settlement(null,4,'HOME','재실행')$$,'P0001','이미 복구된 정산입니다','recovery idempotent');select ok(exists(select 1 from admin_audit_logs where action='SETTLEMENT_RECOVERY'),'recovery audited');select*from finish();rollback;
